prologue:
/* The HUD is read from game_info.txt when a level starts, so nothing here works in AmodInit.
   A key holds either two numbers, one number, or the path of a texture */
static MOD_UNUSED int hud_read(const char* key, AmodValue* value) {
    if (API->hud == 0) return 0;
    memset(value, 0, sizeof *value);
    return API->hud->GetProperty(SELF, key, value);
}

/* at: 0 is the first number of the key, 1 the second */
static MOD_UNUSED float hud_number(const char* key, int at) {
    AmodValue value;
    if (hud_read(key, &value) == 0 || at < 0 || at > 3) return 0.0f;
    if (value.kind == AMOD_VALUE_INT || value.kind == AMOD_VALUE_BOOL) return (float)value.integer;
    return at < (int)value.count ? value.numbers[at] : 0.0f;
}

static MOD_UNUSED const char* hud_text(const char* key) {
    AmodValue value;
    if (hud_read(key, &value) == 0 || value.text == 0) return "";
    return value.text;
}

static MOD_UNUSED void hud_set_numbers(const char* key, int count, float first, float second) {
    AmodValue value;
    if (API->hud == 0) return;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_FLOAT;
    value.count = (uint32_t)count;
    value.numbers[0] = first;
    value.numbers[1] = second;
    API->hud->SetProperty(SELF, key, &value);
}

static MOD_UNUSED void hud_set_text(const char* key, const char* text) {
    AmodValue value;
    if (API->hud == 0) return;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_STRING;
    value.text = text;
    API->hud->SetProperty(SELF, key, &value);
}

static MOD_UNUSED const char* hud_name_at(int index) {
    const char* name = API->hud != 0 ? API->hud->PropertyNameAt(SELF, index) : 0;
    return name != 0 ? name : "";
}
